content:
250          }
   251        zrc = inflateReset (&z);
   252      }
   253
   254    if (unlikely (zrc != Z_OK) || unlikely (z.avail_out != 0))
   255      {
   256        free (buf_out);
   257        buf_out = NULL;
   258        __libelf_seterrno (ELF_E_DECOMPRESS_ERROR);
   259      }
   260
   261    inflateEnd(&z);
   262    return buf_out;
   263  }
