   340  int
   341  elf_compress (Elf_Scn *scn, int type, unsigned int flags)
   342  {
   343    if (scn == NULL)
   344      return -1;
   345
   346    if ((flags & ~ELF_CHF_FORCE) != 0)
   347      {
   348        __libelf_seterrno (ELF_E_INVALID_OPERAND);
   349        return -1;
   350      }
   351
   352    bool force = (flags & ELF_CHF_FORCE) != 0;
   353
   354    Elf *elf = scn->elf;
   355    GElf_Ehdr ehdr;
   356    if (gelf_getehdr (elf, &ehdr) == NULL)
   357      return -1;
   358
   359    int elfclass = elf->class;
   360    int elfdata = ehdr.e_ident[EI_DATA];
   361
   362    Elf64_Xword sh_flags;
   363    Elf64_Word sh_type;
   364    Elf64_Xword sh_addralign;
   365    if (elfclass == ELFCLASS32)
   366      {
   367        Elf32_Shdr *shdr = elf32_getshdr (scn);
   368        if (shdr == NULL)
   369          return -1;
   370
   371        sh_flags = shdr->sh_flags;
   372        sh_type = shdr->sh_type;
   373        sh_addralign = shdr->sh_addralign;
   374      }
   375    else
   376      {
   377        Elf64_Shdr *shdr = elf64_getshdr (scn);
   378        if (shdr == NULL)
   379          return -1;
   380
   381        sh_flags = shdr->sh_flags;
   382        sh_type = shdr->sh_type;
   383        sh_addralign = shdr->sh_addralign;
   384      }
   385
   386    if ((sh_flags & SHF_ALLOC) != 0)
   387      {
   388        __libelf_seterrno (ELF_E_INVALID_SECTION_FLAGS);
   389        return -1;
   390      }
   391
   392    if (sh_type == SHT_NULL || sh_type == SHT_NOBITS)
   393      {
   394        __libelf_seterrno (ELF_E_INVALID_SECTION_TYPE);
   395        return -1;
   396      }
   397
   398    int compressed = (sh_flags & SHF_COMPRESSED);
   399    if (type == ELFCOMPRESS_ZLIB)
   400      {
   401        /* Compress/Deflate.  */
   402        if (compressed == 1)
   403          {
   404            __libelf_seterrno (ELF_E_ALREADY_COMPRESSED);
   405            return -1;
   406          }
   407
   408        size_t hsize = (elfclass == ELFCLASS32
   409                        ? sizeof (Elf32_Chdr) : sizeof (Elf64_Chdr));
   410        size_t orig_size, orig_addralign, new_size;
   411        void *out_buf = __libelf_compress (scn, hsize, elfdata,
   412                                           &orig_size, &orig_addralign,
   413                                           &new_size, force);
   414
   415        /* Compression would make section larger, don't change anything.  */
   416        if (out_buf == (void *) -1)
   417          return 0;
   418
   419        /* Compression failed, return error.  */
   420        if (out_buf == NULL)
   421          return -1;
   422
   423        /* Put the header in front of the data.  */
   424        if (elfclass == ELFCLASS32)
   425          {
   426            Elf32_Chdr chdr;
   427            chdr.ch_type = ELFCOMPRESS_ZLIB;
   428            chdr.ch_size = orig_size;
   429            chdr.ch_addralign = orig_addralign;
   430            if (elfdata != MY_ELFDATA)
   431              {
   432                CONVERT (chdr.ch_type);
   433                CONVERT (chdr.ch_size);
   434                CONVERT (chdr.ch_addralign);
   435              }
   436            memcpy (out_buf, &chdr, sizeof (Elf32_Chdr));
   437          }
   438        else
   439          {
   440            Elf64_Chdr chdr;
   441            chdr.ch_type = ELFCOMPRESS_ZLIB;
   442            chdr.ch_reserved = 0;
   443            chdr.ch_size = orig_size;
   444            chdr.ch_addralign = sh_addralign;
   445            if (elfdata != MY_ELFDATA)
   446              {
   447                CONVERT (chdr.ch_type);
   448                CONVERT (chdr.ch_reserved);
   449                CONVERT (chdr.ch_size);
   450                CONVERT (chdr.ch_addralign);
   451              }
   452            memcpy (out_buf, &chdr, sizeof (Elf64_Chdr));
   453          }
   454
   455        /* Note we keep the sh_entsize as is, we assume it is setup
   456           correctly and ignored when SHF_COMPRESSED is set.  */
   457        if (elfclass == ELFCLASS32)
   458          {
   459            Elf32_Shdr *shdr = elf32_getshdr (scn);
   460            shdr->sh_size = new_size;
   461            shdr->sh_addralign = __libelf_type_align (ELFCLASS32, ELF_T_CHDR);
   462            shdr->sh_flags |= SHF_COMPRESSED;
   463          }
   464        else
   465          {
   466            Elf64_Shdr *shdr = elf64_getshdr (scn);
   467            shdr->sh_size = new_size;
   468            shdr->sh_addralign = __libelf_type_align (ELFCLASS64, ELF_T_CHDR);
   469            shdr->sh_flags |= SHF_COMPRESSED;
   470          }
   471
   472        __libelf_reset_rawdata (scn, out_buf, new_size, 1, ELF_T_CHDR);
   473
   474        /* The section is now compressed, we could keep the uncompressed
   475           data around, but since that might have been multiple Elf_Data
   476           buffers let the user uncompress it explicitly again if they
   477           want it to simplify bookkeeping.  */
   478        scn->zdata_base = NULL;
   479
   480        return 1;
   481      }
   482    else if (type == 0)
   483      {
   484        /* Decompress/Inflate.  */
   485        if (compressed == 0)
   486          {
   487            __libelf_seterrno (ELF_E_NOT_COMPRESSED);
   488            return -1;
   489          }
   490
   491        /* If the data is already decompressed (by elf_strptr), then we
   492           only need to setup the rawdata and section header. XXX what
   493           about elf_newdata?  */
   494        if (scn->zdata_base == NULL)
   495          {
   496            size_t size_out, addralign;
   497            void *buf_out = __libelf_decompress_elf (scn, &size_out, &addralign);
   498            if (buf_out == NULL)
   499              return -1;
   500
   501            scn->zdata_base = buf_out;
   502            scn->zdata_size = size_out;
   503            scn->zdata_align = addralign;
   504          }
   505
   506        /* Note we keep the sh_entsize as is, we assume it is setup
   507           correctly and ignored when SHF_COMPRESSED is set.  */
   508        if (elfclass == ELFCLASS32)
   509          {
   510            Elf32_Shdr *shdr = elf32_getshdr (scn);
   511            shdr->sh_size = scn->zdata_size;
   512            shdr->sh_addralign = scn->zdata_align;
   513            shdr->sh_flags &= ~SHF_COMPRESSED;
   514          }
   515        else
   516          {
   517            Elf64_Shdr *shdr = elf64_getshdr (scn);
   518            shdr->sh_size = scn->zdata_size;
   519            shdr->sh_addralign = scn->zdata_align;
   520            shdr->sh_flags &= ~SHF_COMPRESSED;
   521          }
   522
   523        __libelf_reset_rawdata (scn, scn->zdata_base,
   524                                scn->zdata_size, scn->zdata_align,
   525                                __libelf_data_type (&ehdr, sh_type,
   526                                                    scn->zdata_align));
   527
   528        return 1;
   529      }
   530    else
   220    Elf64_Xword align;
   221    Elf64_Xword flags;
   222    int type;
   223    Elf *elf = scn->elf;
   224
   225    if (elf->class == ELFCLASS32)
   226      {
   227        Elf32_Shdr *shdr
   228          = scn->shdr.e32 ?: __elf32_getshdr_wrlock (scn);
   229
   230        if (shdr == NULL)
   231          /* Something went terribly wrong.  */
   232          return 1;
   233
   234        offset = shdr->sh_offset;
   235        size = shdr->sh_size;
   236        type = shdr->sh_type;
   237        align = shdr->sh_addralign;
   238        flags = shdr->sh_flags;
   239      }
   240    else
   241      {
   242        Elf64_Shdr *shdr
   243          = scn->shdr.e64 ?: __elf64_getshdr_wrlock (scn);
   244
   245        if (shdr == NULL)
   246          /* Something went terribly wrong.  */
   247          return 1;
   248
   249        offset = shdr->sh_offset;
   250        size = shdr->sh_size;
   251        type = shdr->sh_type;
   252        align = shdr->sh_addralign;
   253        flags = shdr->sh_flags;
   254      }
   255
   256    /* If the section has no data (for whatever reason), leave the `d_buf'
   257       pointer NULL.  */
   258    if (size != 0 && type != SHT_NOBITS)
   259      {
   260        /* First a test whether the section is valid at all.  */
   261        size_t entsize;
   262
   263        /* Compressed data has a header, but then compressed data.
   264           Make sure to set the alignment of the header explicitly,
   265           don't trust the file alignment for the section, it is
   266           often wrong.  */
   267        if ((flags & SHF_COMPRESSED) != 0)
   268          {
   269            entsize = 1;
   270            align = __libelf_type_align (elf->class, ELF_T_CHDR);
   271          }
   272        else if (type == SHT_HASH)
   273          {
   274            GElf_Ehdr ehdr_mem;
   275            GElf_Ehdr *ehdr = __gelf_getehdr_rdlock (elf, &ehdr_mem);
   276            if (unlikely (ehdr == NULL))
   277              return 1;
   278            entsize = SH_ENTSIZE_HASH (ehdr);
   279          }
   280        else
   281          {
   282            Elf_Type t = shtype_map[TYPEIDX (type)];
   283            if (t == ELF_T_NHDR && align == 8)
   284              t = ELF_T_NHDR8;
   285            if (t == ELF_T_VDEF || t == ELF_T_NHDR || t == ELF_T_NHDR8
   286                || (t == ELF_T_GNUHASH && elf->class == ELFCLASS64))
   287              entsize = 1;
   288            else
   289              entsize = __libelf_type_sizes[elf->class - 1][t];
   290          }
   291
   292        /* We assume it is an array of bytes if it is none of the structured
   293           sections we know of.  */
   294        if (entsize == 0)
   295          entsize = 1;
   296
   297        if (unlikely (size % entsize != 0))
   298          {
   299            __libelf_seterrno (ELF_E_INVALID_DATA);
   300            return 1;
   301          }
   302
   303        /* We can use the mapped or loaded data if available.  */
   304        if (elf->map_address != NULL)
   305          {
   306            /* First see whether the information in the section header is
   307               valid and it does not ask for too much.  Check for unsigned
   308               overflow.  */
   309            if (unlikely (offset > elf->maximum_size
   310                || elf->maximum_size - offset < size))
   311              {
   312                /* Something is wrong.  */
   313                __libelf_seterrno (ELF_E_INVALID_SECTION_HEADER);
   314                return 1;
   315              }
   316
   317            scn->rawdata_base = scn->rawdata.d.d_buf
   318              = (char *) elf->map_address + elf->start_offset + offset;
   319          }
   320        else if (likely (elf->fildes != -1))
   321          {
   322            /* First see whether the information in the section header is
   323               valid and it does not ask for too much.  Check for unsigned
   324               overflow.  */
   325            if (unlikely (offset > elf->maximum_size
   326                          || elf->maximum_size - offset < size))
   327              {
   328                /* Something is wrong.  */
   329                __libelf_seterrno (ELF_E_INVALID_SECTION_HEADER);
   330                return 1;
   331              }
   332
   333            /* We have to read the data from the file.  Allocate the needed
   334               memory.  */
   335            scn->rawdata_base = scn->rawdata.d.d_buf = malloc (size);
   336            if (scn->rawdata.d.d_buf == NULL)
   337              {
   338                __libelf_seterrno (ELF_E_NOMEM);
   339                return 1;
   340              }
   341
   342            ssize_t n = pread_retry (elf->fildes, scn->rawdata.d.d_buf, size,
   343                                     elf->start_offset + offset);
   344            if (unlikely ((size_t) n != size))
   345              {
   346                /* Cannot read the data.  */
   347                free (scn->rawdata.d.d_buf);
   348                scn->rawdata_base = scn->rawdata.d.d_buf = NULL;
   349                __libelf_seterrno (ELF_E_READ_ERROR);
   350                return 1;
   351              }
   352          }
   353        else
   354          {
   355            /* The file descriptor is already closed, we cannot get the data
   356               anymore.  */
   357            __libelf_seterrno (ELF_E_FD_DISABLED);
   358            return 1;
   359          }
   360      }
   361
   362    scn->rawdata.d.d_size = size;
   363
   364    /* Compressed data always has type ELF_T_CHDR regardless of the
   365       section type.  */
   366    if ((flags & SHF_COMPRESSED) != 0)
   367      scn->rawdata.d.d_type = ELF_T_CHDR;
   368    else
   369      {
   370        GElf_Ehdr ehdr_mem;
   371        GElf_Ehdr *ehdr = __gelf_getehdr_rdlock (elf, &ehdr_mem);
   372        if (unlikely (ehdr == NULL))
   373          return 1;
   374        scn->rawdata.d.d_type = __libelf_data_type (ehdr, type, align);
   375      }
   376    scn->rawdata.d.d_off = 0;
   377
   378    /* Make sure the alignment makes sense.  d_align should be aligned both
   379       in the section (trivially true since d_off is zero) and in the file.
   380       Unfortunately we cannot be too strict because there are ELF files
   381       out there that fail this requirement.  We will try to fix those up
   382       in elf_update when writing out the image.  But for very large
   383       alignment values this can bloat the image considerably.  So here
   384       just check and clamp the alignment value to not be bigger than the
   385       actual offset of the data in the file.  Given that there is always
   386       at least an ehdr this will only trigger for alignment values > 64
   387       which should be uncommon.  */
   388    align = align ?: 1;
   389    if (type != SHT_NOBITS && align > offset)
   390      {
   391        /* Align the offset to the next power of two. Uses algorithm from
   392           https://graphics.stanford.edu/~seander/bithacks.html#RoundUpPowerOf2 */
   393        align = offset - 1;
   394        align |= align >> 1;
   395        align |= align >> 2;
   396        align |= align >> 4;
   397        align |= align >> 8;
   398        align |= align >> 16;
   399        align |= align >> 32;
   400        align++;
   401      }
   402    scn->rawdata.d.d_align = align;
   403    if (elf->class == ELFCLASS32
   404        || (offsetof (struct Elf, state.elf32.ehdr)
   405            == offsetof (struct Elf, state.elf64.ehdr)))
   406      scn->rawdata.d.d_version =
   407        elf->state.elf32.ehdr->e_ident[EI_VERSION];
   408    else
   409      scn->rawdata.d.d_version =
   410        elf->state.elf64.ehdr->e_ident[EI_VERSION];
