    68  #define COPY(name) \
    69        dst->name = shdr->name
    70        COPY (sh_name);
    71        COPY (sh_type);
    72        COPY (sh_flags);
    73        COPY (sh_addr);
    74        COPY (sh_offset);
    75        COPY (sh_size);
    76        COPY (sh_link);
    77        COPY (sh_info);
    78        COPY (sh_addralign);
    79        COPY (sh_entsize);
