    84      {
    85        Elf64_Shdr *shdr
    86          = scn->shdr.e64 ?: __elf64_getshdr_rdlock (scn);
    87
    88        if (shdr == NULL)
    89          {
    90            __libelf_seterrno (ELF_E_INVALID_OPERAND);
    91            goto out;
    92          }
